structure.mermaidSource:
flowchart TD
  start["Início: Avaliação Expletiva"] --> proc_isolar_suprimir["Isole QUE ou É QUE e suprima da oração"]
  proc_isolar_suprimir --> dec_supressao{"Frase permanece correta e sem lacuna sintática?"}
  dec_supressao -- "Não" --> res_nao_expletiva["Não é Expletiva (Função Sintática Própria)"]
  dec_supressao -- "Sim" --> proc_confirma["Confirma-se Partícula / Locução Expletiva de Realce"]
  proc_confirma --> dec_preposicionado{"Estrutura enfatizada antecipada é termo preposicionado?"}
  dec_preposicionado -- "Não" --> res_pontuacao_normal["Expletiva Regular / Pontuação Normal"]
  dec_preposicionado -- "Sim" --> dec_extensao{"Adjunto Adverbial deslocado possui 3 ou mais palavras?"}
  dec_extensao -- "Sim (>= 3 palavras)" --> res_virgula_obrigatoria["Vírgula Obrigatória antes do Sujeito"]
  dec_extensao -- "Não (< 3 palavras)" --> res_virgula_facultativa["Vírgula Facultativa"]

flowchart TD
  start["Início: Destacar o Pronome Relativo (PR)"] --> proc_subst["Substituir PR pelo substantivo antecedente"]
  proc_subst --> proc_ordem["Reescrever a oração na ordem direta: S + V + C"]
  proc_ordem --> dec_suj{"O antecedente responde a 'Quem é que + verbo'?"}
  dec_suj -- "Sim" --> res_suj["Função: Sujeito"]
  dec_suj -- "Não" --> dec_termo{"O antecedente completa Verbo ou Nome?"}
  dec_termo -- "Verbo" --> dec_prep_v{"O antecedente completa o verbo com preposição?"}
  dec_prep_v -- "Sem preposição" --> res_od["Função: Objeto Direto (OD)"]
  dec_prep_v -- "Com preposição" --> res_oi["Função: Objeto Indireto (OI)"]
  dec_termo -- "Nome" --> dec_prep_n{"Completa substantivo abstrato preposicionado?"}
  dec_prep_n -- "Sim" --> res_cn["Função: Complemento Nominal (CN)"]
  dec_prep_n -- "Não" --> res_outro["Função: Outro termo nominal (ex.: Adjunto Adnominal)"]
